using BankSystem.Reporting.Domain.Entities;using BankSystem.Shared.Infrastructure.Extensions;using MassTransit;using Microsoft.EntityFrameworkCore;namespace BankSystem.Reporting.Infrastructure.Data;public class ReportingDbContext(DbContextOptions<ReportingDbContext>o):DbContext(o){public DbSet<ReportDefinition> Definitions=>Set<ReportDefinition>();public DbSet<ReportExecution> Executions=>Set<ReportExecution>();public DbSet<TransactionAnalytics> TransactionAnalytics=>Set<TransactionAnalytics>();protected override void OnModelCreating(ModelBuilder modelBuilder){base.OnModelCreating(modelBuilder);modelBuilder.Entity<TransactionAnalytics>().HasIndex(x=>x.TransactionId).IsUnique();modelBuilder.Entity<TransactionAnalytics>().HasIndex(x=>x.CustomerId);modelBuilder.AddTransactionalOutboxEntities();}}
